const lead = $input.first().json;

const requiredFields = [
  "lead_id",
  "name",
  "company",
  "email",
  "service_required",
  "message"
];

const missingFields = requiredFields.filter(
  field => !lead[field] || String(lead[field]).trim() === ""
);

const emailValid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(lead.email);

const valid = missingFields.length === 0 && emailValid;

return [
  {
    json: {
      ...lead,
      validation: {
        valid,
        missing_fields: missingFields,
        email_valid: emailValid
      }
    }
  }
];

const lead = $input.first().json;

const message = String(lead.message || "").toLowerCase();
const service = String(lead.service_required || "").toLowerCase();
const budget = Number(lead.budget || 0);
const timeline = String(lead.timeline || "").toLowerCase();

const clearRequirement =
  message.length >= 40 &&
  (service.length > 0);

const definedBudget = budget > 0;

const urgentRequirement =
  timeline.includes("today") ||
  timeline.includes("urgent") ||
  timeline.includes("24") ||
  timeline.includes("48") ||
  timeline.includes("2 days");

const highPurchaseIntent =
  message.includes("need") ||
  message.includes("ready") ||
  message.includes("hire") ||
  message.includes("looking for") ||
  message.includes("want");

const suitableService =
  service.includes("automation") ||
  service.includes("ai") ||
  service.includes("lead") ||
  service.includes("crm");

const completeContactInfo =
  Boolean(lead.name) &&
  Boolean(lead.email) &&
  Boolean(lead.company);

return [
  {
    json: {
      ...lead,
      analysis: {
        clear_requirement: clearRequirement,
        defined_budget: definedBudget,
        urgent_requirement: urgentRequirement,
        high_purchase_intent: highPurchaseIntent,
        suitable_service: suitableService,
        complete_contact_info: completeContactInfo
      }
    }
  }
];

const lead = $input.first().json;
const analysis = lead.analysis || {};

let score = 0;

if (analysis.clear_requirement) score += 20;
if (analysis.defined_budget) score += 15;
if (analysis.urgent_requirement) score += 15;
if (analysis.high_purchase_intent) score += 20;
if (analysis.suitable_service) score += 20;
if (analysis.complete_contact_info) score += 10;

let priority;

if (score >= 80) {
  priority = "High Priority";
} else if (score >= 60) {
  priority = "Medium Priority";
} else if (score >= 40) {
  priority = "Low Priority";
} else {
  priority = "Nurture / Review";
}

return [{
  json: {
    ...lead,
    score,
    priority
  }
}];

const lead = $input.first().json;
const analysis = lead.analysis || {};

let recommendedAction;
let followUpPriority;

if (lead.priority === "High Priority" && analysis.urgent_requirement) {
  recommendedAction = "Contact immediately";
  followUpPriority = "High";
} else if (lead.priority === "High Priority") {
  recommendedAction = "Schedule sales call";
  followUpPriority = "High";
} else if (
  lead.priority === "Medium Priority" &&
  analysis.high_purchase_intent
) {
  recommendedAction = "Follow up within 2 business days";
  followUpPriority = "Medium";
} else if (
  lead.priority === "Low Priority" &&
  analysis.clear_requirement
) {
  recommendedAction = "Send qualification follow-up";
  followUpPriority = "Low";
} else if (!analysis.complete_contact_info) {
  recommendedAction = "Request missing contact information";
  followUpPriority = "Low";
} else {
  recommendedAction = "Nurture / request more information";
  followUpPriority = "Low";
}

return [{
  json: {
    ...lead,
    recommended_action: recommendedAction,
    follow_up_priority: followUpPriority
  }
}];

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
  item.json.myNewField = 1;
}

return $input.all();
